// Pull the message array out of the inbox response and normalise field names.
const cfg = $('Config').first().json;
const map = cfg.fieldMap || {};

for (const [k, v] of Object.entries(map)) {
  if (!v || String(v).startsWith('REPLACE_ME')) {
    throw new Error(`fieldMap.${k} is still REPLACE_ME - fill it in from the Explee OpenAPI schema (see explee/README.md).`);
  }
}

const raw = $input.first().json;
const arrayField = cfg.inboxArrayField;
const list = arrayField && !arrayField.startsWith('REPLACE_ME')
  ? arrayField.split('.').reduce((o, k) => (o ?? {})[k], raw)
  : (Array.isArray(raw) ? raw : null);

if (!Array.isArray(list)) {
  throw new Error('Could not find the message array. Set Config.inboxArrayField to the JSON path of the array (e.g. "data" or "data.messages").');
}

const get = (obj, path) => path.split('.').reduce((o, k) => (o ?? {})[k], obj);

return list.map((m) => ({
  json: {
    messageId: get(m, map.messageId),
    threadId: get(m, map.threadId),
    leadEmail: get(m, map.leadEmail),
    leadName: get(m, map.leadName),
    body: get(m, map.body),
    campaignId: get(m, map.campaignId),
    direction: get(m, map.direction),
    _raw: m,
  },
}));

// Guardrails. Anything filtered out here can never be replied to.
const cfg = $('Config').first().json;
const store = $getWorkflowStaticData('global');
store.handled = store.handled || {};

// Forget anything older than 30 days so the store does not grow forever.
const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
for (const [id, ts] of Object.entries(store.handled)) {
  if (ts < cutoff) delete store.handled[id];
}

const HARD_STOP = /\b(unsubscribe|opt.?out|remove me|stop emailing|take me off|do not contact|GDPR|legal action|lawyer|attorney)\b/i;
const AUTO_REPLY = /\b(out of office|automatic reply|auto.?reply|on (vacation|holiday|leave)|maternity leave|paternity leave|no longer with|has left the company|undeliverable|mail delivery|delivery status notification)\b/i;

const out = [];
for (const item of $input.all()) {
  const m = item.json;

  if (!m.messageId || !m.threadId) continue;                        // unusable
  if (store.handled[m.messageId]) continue;                          // already processed
  if (String(m.direction).toLowerCase().includes('out')) continue;   // our own sent mail
  if (!m.body || String(m.body).trim().length < 2) continue;

  const body = String(m.body);

  if (HARD_STOP.test(body)) {
    store.handled[m.messageId] = Date.now();
    out.push({ json: { ...m, action: 'needs_human', reason: 'opt-out / legal language - never auto-reply', preClassified: true } });
    continue;
  }
  if (AUTO_REPLY.test(body)) {
    store.handled[m.messageId] = Date.now();
    out.push({ json: { ...m, action: 'no_action', reason: 'auto-responder / bounce', preClassified: true } });
    continue;
  }

  out.push({ json: { ...m, preClassified: false } });
}

// Rate limit per run so a bad prompt cannot blast the whole inbox.
const limit = Number(cfg.maxRepliesPerRun) || 10;
const live = out.filter((i) => !i.json.preClassified).slice(0, limit);
const passthrough = out.filter((i) => i.json.preClassified);

for (const i of live) {
  i.json.classifierBody = {
    model: cfg.model,
    max_tokens: 400,
    output_config: { effort: 'low' },
    system: [
      'You triage replies to a B2B cold outreach campaign.',
      'Context on the sender: ' + cfg.companyContext,
      '',
      'Classify the prospect reply into exactly one intent:',
      '  interested      - wants to know more, asks about pricing/features, says yes',
      '  meeting_request - explicitly wants a call, demo or time slot',
      '  question        - a specific factual question before deciding',
      '  referral        - points to a different person or team',
      '  not_now         - open but wrong timing ("circle back in Q3")',
      '  not_interested  - a clear no, without opt-out language',
      '  unclear         - anything you are not confident about',
      '',
      'Then choose an action:',
      '  reply       - only for interested, meeting_request, question, referral, not_now',
      '  no_action   - for not_interested',
      '  needs_human - for unclear, anything hostile, anything about pricing negotiation,',
      '                contracts, security review, or where a wrong answer would cost the deal',
      '',
      'Be conservative. When in doubt, needs_human. Never guess a fact about the product.',
      '',
      'Respond with ONLY a JSON object, no prose, no code fence:',
      '{"intent":"...","action":"...","confidence":0.0,"reason":"one short sentence"}',
    ].join('\n'),
    messages: [
      {
        role: 'user',
        content: 'From: ' + (i.json.leadName || 'unknown') + ' <' + (i.json.leadEmail || 'unknown') + '>\n\nReply:\n"""\n' + String(i.json.body).slice(0, 6000) + '\n"""',
      },
    ],
  };
}

return [...live, ...passthrough];

// Merge the model's verdict back onto the message and build the drafting request.
const cfg = $('Config').first().json;
const src = $('Guardrails & Dedupe').all().filter((i) => !i.json.preClassified);
const out = [];

const items = $input.all();
for (let idx = 0; idx < items.length; idx++) {
  const res = items[idx].json;
  const msg = src[idx] ? { ...src[idx].json } : {};

  const text = (res.content || [])
    .filter((b) => b.type === 'text')
    .map((b) => b.text)
    .join('')
    .trim();

  let verdict;
  try {
    const m = text.match(/\{[\s\S]*\}/);
    verdict = JSON.parse(m ? m[0] : text);
  } catch (e) {
    verdict = { intent: 'unclear', action: 'needs_human', confidence: 0, reason: 'classifier output was not valid JSON' };
  }

  // Low confidence never auto-replies.
  if (Number(verdict.confidence) < 0.7 && verdict.action === 'reply') {
    verdict.action = 'needs_human';
    verdict.reason = 'low confidence (' + verdict.confidence + ') - ' + verdict.reason;
  }

  msg.intent = verdict.intent;
  msg.action = verdict.action;
  msg.confidence = verdict.confidence;
  msg.reason = verdict.reason;

  if (msg.action === 'reply') {
    const hasLink = cfg.bookingLink && !String(cfg.bookingLink).startsWith('REPLACE_ME');
    msg.draftBody = {
      model: cfg.model,
      max_tokens: 1000,
      output_config: { effort: 'medium' },
      system: [
        'You write short replies on behalf of ' + cfg.senderName + ', in a B2B outreach inbox.',
        'Product context: ' + cfg.companyContext,
        hasLink
          ? 'Booking link (use only for a meeting request): ' + cfg.bookingLink
          : 'There is no booking link configured - never invent one.',
        '',
        'Rules:',
        '- Under 90 words. Plain text. No markdown, no bullet lists.',
        '- Match their tone and reply in the language they wrote in.',
        '- Answer only what you actually know from the product context above.',
        '  If they asked something not covered there, say you will confirm and come back.',
        '- Never invent pricing, features, integrations, customer names or numbers.',
        '- One clear next step at the end. No hard sell. Never use "just" or "simply".',
        '- Sign off as ' + cfg.senderName + '. Do not add a subject line.',
        '',
        'Respond with ONLY a JSON object, no prose, no code fence:',
        '{"reply":"the full email body","needs_human":false,"note":""}',
        'Set needs_human to true if you cannot write a safe, accurate reply.',
      ].join('\n'),
      messages: [
        {
          role: 'user',
          content: 'Intent: ' + msg.intent + '\nFrom: ' + (msg.leadName || 'unknown') + ' <' + (msg.leadEmail || 'unknown') + '>\n\nTheir reply:\n"""\n' + String(msg.body).slice(0, 6000) + '\n"""',
        },
      ],
    };
  }

  out.push({ json: msg });
}

// Re-attach the messages that were decided by the regex guardrails.
for (const i of $('Guardrails & Dedupe').all().filter((x) => x.json.preClassified)) {
  out.push({ json: i.json });
}

return out;

const src = $('Should Reply?').all();
const out = [];
const items = $input.all();

for (let idx = 0; idx < items.length; idx++) {
  const res = items[idx].json;
  const msg = src[idx] ? { ...src[idx].json } : {};

  const text = (res.content || [])
    .filter((b) => b.type === 'text')
    .map((b) => b.text)
    .join('')
    .trim();

  let draft;
  try {
    const m = text.match(/\{[\s\S]*\}/);
    draft = JSON.parse(m ? m[0] : text);
  } catch (e) {
    draft = { reply: '', needs_human: true, note: 'drafter output was not valid JSON' };
  }

  const body = String(draft.reply || '').trim();

  // Final safety net before anything can be sent.
  if (draft.needs_human === true || body.length < 20 || body.length > 1500 || /REPLACE_ME|\{\{|lorem ipsum/i.test(body)) {
    msg.action = 'needs_human';
    msg.reason = draft.note || 'draft failed validation';
  }
  msg.draft = body;

  delete msg.draftBody;
  out.push({ json: msg });
}

return out;

// Mark as handled only after a successful send, so a failure retries next run.
const store = $getWorkflowStaticData('global');
store.handled = store.handled || {};
for (const i of $('Auto-send Enabled?').all()) {
  if (i.json.messageId) store.handled[i.json.messageId] = Date.now();
}
return $input.all();
